-- purpose: 令和7年第2回(6月)定例会のデータを会議録から新規投入する
-- affected: assemblies, agenda_items, general_questions, question_topics
-- sources:
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070604.pdf (6/4 開会・一般質問)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070611.pdf (6/11 議案審議・閉会)
-- notes: total_agenda_itemsは開会時の町長挨拶で示された「報告2件、条例の一部改正2件、
--        補正予算3件の計7件」に基づく。議案第40号(広川町特別職の職員で非常勤のものの
--        報酬及び費用弁償に関する条例の一部改正)は、根拠となる国会議員の選挙等の執行
--        経費の基準に関する法律の一部改正が6/4(開会日)に公布されたことを受けて追加
--        提出されたもので(会議録に「追加でお配りいたしました議案書」との記載あり)、
--        開会時の「計7件」には含まれない。r7-3・r7-4の発委・発議と同様の扱いで
--        agenda_itemsに8件目として追加登録する。
--        agenda_items.statusはCHECK制約(可決・否決・継続審査・撤回・未審議のみ)に対応するため、
--        報告→可決の変換ルールを適用。議案第35号は起立採決で起立多数により可決
--        (反対討論:江藤美代子議員、賛成討論:栗原福裕議員)。
--        council_membersは一般質問した7名(竹下英治・下田めぐみ・梶原一美・池尻浩一・
--        辻満晴・江藤美代子・藤島玄稔)全員が既存レコードで解決できるため、新規作成は行わない。

do $$
declare
  v_assembly_id uuid := '8bab3223-6710-43de-8513-59a82987ba94';
begin

  -- 冪等ガード: 既に投入済みなら何もしない
  if exists (
    select 1 from public.assemblies
    where fiscal_year = 2025
      and session_type = '定例会'
      and session_number = 2
  ) then
    raise notice '既に投入済みのためスキップします';
    return;
  end if;

  insert into public.assemblies
    (id, name, session_type, session_number, fiscal_year, start_date, end_date, total_agenda_items)
  values
    (v_assembly_id, '令和7年第2回定例会', '定例会', 2, 2025, '2025-06-04', '2025-06-11', 7);

  -- agenda_items
  insert into public.agenda_items
    (id, assembly_id, item_number, title, category, proposal_reason, status, decided_on, display_order)
  values
    ('68aef8c6-b0b3-4b73-9cdf-a1791ebc225c', v_assembly_id, '報告第2号', '令和6年度広川町一般会計繰越明許費繰越計算書の報告について', '報告', '地方自治法施行令第146条第2項の規定による報告。令和7年3月定例会で承認された16事業・合計604,405千円の繰越明許のうち、公共土木施設補助災害復旧費が確定したことに伴い一部減額し、総額595,737千円を令和7年度に繰り越した。', '可決', '2025-06-11', 1),
    ('90a803d8-9193-45a5-8714-c7590cd7430d', v_assembly_id, '報告第3号', '令和6年度広川町国民健康保険特別会計繰越明許費繰越計算書の報告について', '報告', '地方自治法施行令第146条第2項の規定による報告。システム標準化対応テストプリント委託料259千円の繰越明許について、同額を令和7年度に繰り越した。', '可決', '2025-06-11', 2),
    ('d1b2fe05-fe32-4308-93bf-a1fbade2c312', v_assembly_id, '議案第35号', '広川町個人番号の利用及び特定個人情報の提供に関する条例の一部改正について', '条例の改正', '地方公共団体情報システムの標準化に伴う住登外者宛名番号管理機能の実装により、個人番号の独自利用事務が新たに整理され、他の事務処理との連携が必要とされることから改正するもの。江藤美代子議員は個人情報の外部委託・運用経費増加への懸念から反対討論、栗原福裕議員は住民サービス低下防止の観点から賛成討論を行い、起立採決の結果、起立多数で可決された。', '可決', '2025-06-11', 3),
    ('060e48ef-d141-47e6-b1f2-0010f6ede219', v_assembly_id, '議案第36号', '広川町町税条例の一部改正について', '条例の改正', '地方税法等の一部を改正する法律の施行により改正するもの。特定親族特別控除の創設(扶養親族等所得要件480千円→580千円への引上げに伴う経過措置)、加熱式たばこの課税方式見直し、公示送達のインターネット活用等が主な内容。', '可決', '2025-06-11', 4),
    ('8b693a68-a27c-4656-9884-4c5e77e76976', v_assembly_id, '議案第37号', '令和7年度広川町一般会計補正予算（第2号）について', '補正予算', '歳入歳出予算の総額に歳入歳出それぞれ205,675千円を追加し、予算総額を9,738,615千円とするもの。竜光寺公園リニューアル工事(観光庁の地域における受入環境整備促進事業補助金を活用したトイレ・駐車場整備、単独・補助合わせ約1.3億円)、定額減税を補足する調整給付金給付事業の確定に伴う増額等が主な内容。', '可決', '2025-06-11', 5),
    ('581e38c3-ebf9-4691-aa80-d651379ec487', v_assembly_id, '議案第38号', '令和7年度広川町国民健康保険特別会計補正予算（第1号）について', '補正予算', '既定の予算総額に277千円を追加し、予算総額を2,279,132千円とするもの。国民健康保険システム改修委託料の増額が内容。', '可決', '2025-06-11', 6),
    ('22261d3b-41fa-4fb4-ae81-b9c47c7204cb', v_assembly_id, '議案第39号', '令和7年度広川町後期高齢者医療特別会計補正予算（第1号）について', '補正予算', '既定の予算総額に490千円を追加し、予算総額を374,761千円とするもの。マイナ保険証保有者にも資格確認書を郵送する暫定運用継続に伴う後期高齢者医療一般管理費の増額が内容。', '可決', '2025-06-11', 7),
    ('ac62be40-20e2-4f7d-b632-018de0a69f33', v_assembly_id, '議案第40号', '広川町特別職の職員で非常勤のものの報酬及び費用弁償に関する条例の一部改正について', '条例の改正', '国会議員の選挙等の執行経費の基準に関する法律の一部改正(令和7年6月4日公布)に伴う物価変動を踏まえた基準額見直しにより、選挙長・開票管理者、投票管理者、選挙立会人・開票立会人等の報酬額を改定するもの。', '可決', '2025-06-11', 8);

  -- general_questions: council_member_idは氏名で既存レコードを解決する
  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'd9e583a5-ca49-4d02-b927-05a1629872bc', v_assembly_id, cm.id, 1, '広川町農業の支援策、防犯カメラ、職員定数増員、人材育成基本方針、ネイティブテキスタイル産地プロジェクトについて'
  from public.council_members cm where cm.name = '竹下英治';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'b2c41f0c-4285-46f4-9d84-0efc371c088d', v_assembly_id, cm.id, 2, 'クーリングシェルターの設置、教育支援センターについて'
  from public.council_members cm where cm.name = '下田めぐみ';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select '19777cfc-19ec-43e7-8f35-f7e9fb89a51f', v_assembly_id, cm.id, 3, '教育支援センター、水泳授業の民間委託、上広川小学校移転計画について'
  from public.council_members cm where cm.name = '梶原一美';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select '981401c5-dd73-466c-b2de-251d0e23ea7a', v_assembly_id, cm.id, 4, '民生委員・児童委員の在り方、公民館の整備活用について'
  from public.council_members cm where cm.name = '池尻浩一';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'a2a77c56-5c4b-4ec9-ae7c-dbf61347f7c6', v_assembly_id, cm.id, 5, 'ふるさと納税の取扱い、農地の有効利用の取組について'
  from public.council_members cm where cm.name = '辻満晴';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select '8244c212-0a6e-42b9-8b1d-45417e069d95', v_assembly_id, cm.id, 6, '学校現場の状況、同和対策事業について'
  from public.council_members cm where cm.name = '江藤美代子';

  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', v_assembly_id, cm.id, 7, '都市計画区域、働く場の創設、教育・文化環境の充実、道徳教育、人材確保と人材育成について'
  from public.council_members cm where cm.name = '藤島玄稔';

  -- question_topics: 会議録の質疑応答の内容に基づく
  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('e00af13f-a757-414c-a390-6d74bff88e19', 'd9e583a5-ca49-4d02-b927-05a1629872bc', '広川町農業の就業人口減少対策', '広川町の農業就業人口減少に対し、国・県・町が新規就農者確保・育成やハード面の補助(新規就農者育成総合対策の経営発展支援事業、青年等就農資金等)を実施していると説明。町独自では新規就農支援員の配置(令和2年度から)や町外からの定住促進の家賃補助を実施。竹下議員は9月以降に農業問題をさらに深掘りする意向を示し、今回は事実確認にとどめた。', '産業課', 1),
    ('d2a303e6-f035-4385-b681-e0004c3e815e', 'd9e583a5-ca49-4d02-b927-05a1629872bc', '防犯カメラの運用体制', '広川町安全安心防犯カメラの設置及び運用に関する要綱(平成26年度策定)に基づく運用体制を確認。これまでの外部提供実績は57件・80台分、提供判断は管理責任者(企画課長)が行う。録画データは2週間で上書き、外部委託でなく職員によるチェックを継続する方針。総合計画では今後2か年で40台までの設置を目指すとされている。', '企画課', 2),
    ('6a8618ce-9008-4fce-86ec-62fbcc38d9e3', 'd9e583a5-ca49-4d02-b927-05a1629872bc', '職員定数増員の配置状況', '昨年度の職員定数増(10名程度)後の配置状況について、浸水対策・国道3号関連・こどもまんなか部門・総務企画部門を中心に、土木・文化財・社会福祉士等の専門職種を重点的に採用予定と説明。早期退職者の増加はコロナを境とした若手の転職意識の変化や令和5年豪雨災害対応の負担等が要因とされた。', '総務課', 3),
    ('58a8ec2a-d940-4750-a3e4-16bc6ca55260', 'd9e583a5-ca49-4d02-b927-05a1629872bc', '広川町人材育成基本方針', '本年3月策定の人材育成基本方針について、平成25年策定版との違いを質問。総務課長は、前回は内容が職員に十分周知されず意識づけができていなかったとし、今回は職員の意見を吸い上げながら策定した点が異なると説明。朝礼の励行・研修発表の機会・希望降任制度は現在も運用中と回答があった。', '総務課', 4),
    ('a64bd261-a216-4e96-be24-7c45e5f6026d', 'd9e583a5-ca49-4d02-b927-05a1629872bc', 'ネイティブテキスタイル産地プロジェクト', '地方創生2.0の新しい地方経済・生活環境創生交付金を活用し、令和7年度から3か年事業として採択。OrigeとHodokuを拠点施設として指定管理者を新たに選定予定。竹下議員は既存の織元事業との違いや産業展示会館(商工会指定管理)との役割整理について疑問を呈し、優先順位や事業効果の検証(PDCA)を求めた。', '産業課', 5),
    ('5902853c-0b8a-4b22-8ca6-37c534841836', 'b2c41f0c-4285-46f4-9d84-0efc371c088d', 'クーリングシェルター(猛暑対策)の設置検討', '猛暑対策として、町は広報・LINE・dボタン等での注意喚起や高齢者宅訪問時の啓発チラシ配布を実施。クーリングシェルターは本町ではまだ具体的な指定を行っておらず、役場庁舎や町民交流センター等の公共施設を早急に指定する方向で検討中と町長が答弁。高齢化率は上広川40.2%・中広川26.5%・下広川30.3%、独居世帯割合も高いことが福祉課長より示された。', '環境課', 1),
    ('b20a3067-caac-4c9f-b997-8093793591ac', 'b2c41f0c-4285-46f4-9d84-0efc371c088d', '教育支援センターの設置に向けた検討状況', '令和8年4月、広川町保健・福祉センターはなやぎの里2階に教育支援センターを開設予定。不登校児童・生徒は令和6年度小学校14名・中学校35名で増加傾向。八女市「あしたば」への通所者(2名)の送迎負担が設置の契機。対象者数は10名程度、指導員2〜3名配置を想定。下田議員は入り口の配慮など不登校児童・生徒への心理的ハードルへの対応や、現場の声を反映した運営を求めた。', '教育委員会事務局子ども課', 2),
    ('c635ef5e-274d-4421-9970-9d456359bd17', '19777cfc-19ec-43e7-8f35-f7e9fb89a51f', '教育支援センターの概要・理念', '教育機会確保法(平成28年制定)や文科省通知(令和元年)の理念を踏まえ、学校復帰のみを目標とせず社会的自立を支援する方針であることを確認。梶原議員は場所(はなやぎの里)の選定について、空き家活用等も含めたより多様な検討の必要性や、不登校の原因(無気力・不安・生活リズムの乱れ等)に応じた配慮、八女市「あしたば」との連携協定の可能性について質疑した。運営は町直営、教育支援センター通所は指導要録上の出席扱いとする方向。', '教育委員会事務局子ども課', 1),
    ('885c6364-8130-4e1c-a8b0-1ffc03e7628e', '19777cfc-19ec-43e7-8f35-f7e9fb89a51f', '水泳授業の民間委託(広川中学校試行)', '上広川・下広川小学校での試行実施に続き、本年度はプール老朽化が進む広川中学校で水泳授業の民間委託を試行。生徒・保護者・職員アンケートを実施し、費用や所要時間等のエビデンスも含めた報告書としてまとめる方針。', '教育委員会事務局子ども課', 2),
    ('c6658350-b6f5-45bd-a0ce-c75c70d67900', '19777cfc-19ec-43e7-8f35-f7e9fb89a51f', '上広川小学校移転計画の進捗', '国道3号広川八女バイパス事業に伴う移転について、福岡国道事務所からの具体的スケジュール提示はまだないが、幅ぐい設置・用地測量が6月から開始される見込み(区長として現地の説明を受けたとの発言あり)。町は今後の児童数推移等の基礎資料収集を行っており、検討委員会の立ち上げに向けて準備を進めている段階。', '教育委員会事務局子ども課', 3),
    ('b1714c95-ca20-4745-9677-37be9c26a843', '981401c5-dd73-466c-b2de-251d0e23ea7a', '民生委員・児童委員の在り方', '広川町の民生委員は現在40名活動(定員42名、2行政区が定員未充足)。活動費は県内でも高水準(県活動費61,700円+町補助金月8千円×12か月+社協補助金)。福祉課長は、担い手不足や活動の周知不足を課題として認識し、令和6年度のワークショップで出た意見を12月改選に向けて反映していく方針と説明。', '福祉課', 1),
    ('fa203586-9ed7-4065-8deb-535bf05610d6', '981401c5-dd73-466c-b2de-251d0e23ea7a', '公民館の整備活用', 'こどもまんなかプロジェクトの一環として、あつまれ公民館事業・子どもの居場所づくりアドバイザー事業を本年度新設し、分館長会と協議中。遊具整備補助(平成29〜令和3年度、18行政区36か所)やWi-Fi整備補助(令和3〜4年度、14行政区)は国の交付金終了に伴い現在は実施していない。池尻議員は分館長会を核とした地域力強化の重要性を指摘した。', '生涯学習課', 2),
    ('79a08acc-6fc3-427c-8f51-5aa3fb694c27', 'a2a77c56-5c4b-4ec9-ae7c-dbf61347f7c6', 'ふるさと納税の取扱い状況', '令和6年度寄付額236,690,600円(前年度比約154%増)、返礼品は町特産品421品目(全体の33%)だが寄付額ベースでは約78%を占める。広川サービスエリアの店舗型ふるさと納税は令和6年11月開始、実績245千円。令和7年度目標4億円・8年度目標8億円に対し、辻議員は目標達成に向けた取組の充実を求めた。', '企画課', 1),
    ('59e3396c-79ae-42ef-ae6b-20dc73bd9f50', 'a2a77c56-5c4b-4ec9-ae7c-dbf61347f7c6', '農地の有効利用の取組', '圃場整備完了地区等8地区の地域計画を令和7年3月末に策定・公表済み。本年4月から農地の貸借は原則、農地中間管理機構を経由する制度に一本化(特段の不満は出ていないとの答弁)。太田地区では荒廃農地が農業委員・農地最適化利用推進委員の働きかけで新たな借手が見つかり解消した事例を紹介。辻議員は地域計画の農家への周知徹底を求めた。', '産業課', 2),
    ('545131b9-364a-4c91-b452-20276477fc71', '8244c212-0a6e-42b9-8b1d-45417e069d95', '学校現場の状況(教員配置・超過勤務)', '本年度の正規教員配置は小学校3校合計19名・中学校12名の欠員が生じたが、県登録講師や町負担の非常勤講師の配置で対応。教員の月45時間超過勤務の割合は、小学校33.2%(全国平均24.8%より高い)、中学校27.4%(全国平均42.5%より低い)。学習支援員の配置や2学期制導入等により負担軽減を図っていると答弁。', '教育委員会事務局子ども課', 1),
    ('318c9b3c-ef0d-4322-976f-72afba7e5418', '8244c212-0a6e-42b9-8b1d-45417e069d95', '同和対策事業', '特別措置法終了(平成14年)後も広川町では運動団体への助成金(3団体)・部落解放会館運営費負担金・人権啓発事業等を一般対策として継続。江藤議員は、県民意識調査で「特別な対策自体が差別」と考える人が約4割(そう思う17.4%+どちらかというと22.5%)いることを示し、特定地域を対象とした事業(同和地区文化活動補助金382千円等)の縮小・完了を求めたが、町長は地域や関係団体との連携の必要性を強調し、継続の立場を示した。', '生涯学習課', 2),
    ('10466b18-6251-4016-9806-110e7fab4e8e', '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', '都市計画区域', '広川町は昭和50年から町全域が都市計画区域(非線引き)に指定され、市街化区域・調整区域の区分や用途地域指定はなし。建設課長は、区域区分を設定すると開発許可の要件が厳しくなる場合があるとして、現状維持が開発の観点からは望ましいとの見解を示した。', '建設課', 1),
    ('eb871f17-26d2-4517-8c42-bb00840df2e0', '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', '働く場の創設(企業誘致)', '広川中核工業団地・久留米広川新産業団地は全区画稼働中、従業員に占める広川町民の割合は21%。新産業団地は平成19〜20年頃から売り出しを開始し、平成28年頃に全区画売却が完了(隣接する久留米市分が先行完売する中での取組だった)。町は工業団地連絡協議会等を通じ、地元就業促進や新規参入企業の情報収集を継続する方針。', '産業課', 2),
    ('6b2664de-8889-4758-9f93-4f78f498fbe9', '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', '教育・文化環境の充実(学校施設・図書館)', '学校施設整備は要望を踏まえヒアリング・現地調査の上で次年度予算に反映。学校図書館は全国学校図書館協議会の基準に沿って選定・廃棄を実施。町立図書館は大活字本802冊を所蔵、専門的な学術書籍は県立図書館等との連携で対応。郷土資料・絶版書籍は除籍対象外。', '生涯学習課', 3),
    ('6cbe5f1c-bb0e-4381-b586-eca0cf847f72', '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', '道徳教育', '学習指導要領に基づき、校長の方針の下で全教員が協力して道徳教育の全体計画を推進。特別活動(卒業式等の学校行事)を通じた実践的態度の育成も道徳教育の一環と位置づけられている。', '教育委員会事務局子ども課', 4),
    ('8ef58673-c3a6-4791-822a-0e27ba0cfb98', '0e6b8ee6-b0dc-4fa0-b37b-15aa1ba15b50', '人材確保と人材育成', '本年度の職員採用試験では教養試験を廃止し自己アピールシート方式を導入、一般事務58名・土木8名・文化財5名・社会福祉士9名の応募があり、転職希望者が一定数含まれることが判明。人事評価は職員の自己目標設定を起点に係長・課長が評価し管理職がフィードバックする方式。会計年度任用職員には正職員化を希望する者が一定数いるとの答弁があった。', '総務課', 5);

end $$;
